","import React from "react";
import type { Severity } from "../../data/mockData";
import { sevColor } from "./severity";

// ---- Radial gauge (semi/full circular arc with centered value) ----
export function RadialGauge({
 value,
 max = 100,
 label,
 sublabel,
 severity = "healthy",
 size = 132
}: {
 value: number;
 max?: number;
 label?: string;
 sublabel?: string;
 severity?: Severity;
 size?: number;
}) {
 const r = size / 2 - 10;
 const c = 2 * Math.PI * r;
 const pct = Math.max(0, Math.min(1, value / max));
 const dash = c * 0.75; // 270deg arc
 const offset = dash * (1 - pct);
 return (
 <div className="grc-gauge" style={{ width: size, height: size }}>
 <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
 <g transform={`rotate(135 ${size / 2} ${size / 2})`}>
 <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="10"
 stroke="rgba(var(--grc-track),0.9)" strokeDasharray={`${dash} ${c}`} strokeLinecap="round" />
 <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="10"
 stroke={sevColor(severity)} strokeDasharray={`${dash} ${c}`} strokeDashoffset={offset}
 strokeLinecap="round" className="grc-gauge__arc" />
 </g>
 </svg>
 <div className="grc-gauge__center">
 <span className="grc-gauge__value">{label ?? value}</span>
 {sublabel ? <span className="grc-gauge__sub">{sublabel}</span> : null}
 </div>
 </div>
 );
}

// ---- Progress ring (full circle %) ----
export function ProgressRing({ value, severity = "healthy", size = 64, text }: { value: number; severity?: Severity; size?: number; text?: string }) {
 const r = size / 2 - 6;
 const c = 2 * Math.PI * r;
 const offset = c * (1 - value / 100);
 return (
 <div className="grc-ring" style={{ width: size, height: size }}>
 <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
 <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="6" stroke="rgba(var(--grc-track),0.9)" />
 <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="6" stroke={sevColor(severity)}
 strokeDasharray={c} strokeDashoffset={offset} strokeLinecap="round"
 transform={`rotate(-90 ${size / 2} ${size / 2})`} className="grc-ring__arc" />
 </svg>
 <span className="grc-ring__text">{text ?? `${value}%`}</span>
 </div>
 );
}

// ---- Multi-segment donut ----
export function Donut({ segments, size = 120, center }: { segments: { value: number; severity: Severity; label?: string }[]; size?: number; center?: React.ReactNode }) {
 const r = size / 2 - 8;
 const c = 2 * Math.PI * r;
 const total = segments.reduce((a, s) => a + s.value, 0) || 1;
 let acc = 0;
 return (
 <div className="grc-donut" style={{ width: size, height: size }}>
 <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
 <circle cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="12" stroke="rgba(var(--grc-track),0.6)" />
 {segments.map((s, i) => {
 const frac = s.value / total;
 const seg = c * frac;
 const gap = c - seg;
 const off = -acc * c;
 acc += frac;
 return (
 <circle key={i} cx={size / 2} cy={size / 2} r={r} fill="none" strokeWidth="12"
 stroke={sevColor(s.severity)} strokeDasharray={`${seg} ${gap}`} strokeDashoffset={off}
 transform={`rotate(-90 ${size / 2} ${size / 2})`} />
 );
 })}
 </svg>
 {center ? <div className="grc-donut__center">{center}</div> : null}
 </div>
 );
}

// ---- Sparkline (line + optional area) ----
export function Sparkline({ data, severity = "info", area = true, width = 120, height = 36 }: { data: number[]; severity?: Severity; area?: boolean; width?: number; height?: number }) {
 const min = Math.min(...data);
 const max = Math.max(...data);
 const span = max - min || 1;
 const step = width / (data.length - 1 || 1);
 const pts = data.map((d, i) => `${i * step},${height - ((d - min) / span) * (height - 6) - 3}`);
 const path = `M${pts.join(" L")}`;
 const col = sevColor(severity);
 return (
 <svg className="grc-spark" width={width} height={height} viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none">
 {area ? <path d={`${path} L${width},${height} L0,${height} Z`} fill={col} opacity="0.12" /> : null}
 <path d={path} fill="none" stroke={col} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
 <circle cx={(data.length - 1) * step} cy={height - ((data[data.length - 1] - min) / span) * (height - 6) - 3} r="2.5" fill={col} />
 </svg>
 );
}

// ---- Micro bars ----
export function MicroBars({ data, severity = "info", width = 120, height = 36 }: { data: number[]; severity?: Severity; width?: number; height?: number }) {
 const max = Math.max(...data) || 1;
 const bw = width / data.length - 3;
 const col = sevColor(severity);
 return (
 <svg className="grc-bars" width={width} height={height} viewBox={`0 0 ${width} ${height}`} preserveAspectRatio="none">
 {data.map((d, i) => {
 const h = (d / max) * (height - 4);
 return <rect key={i} x={i * (bw + 3)} y={height - h} width={bw} height={h} rx="1.5" fill={col} opacity={0.45 + 0.55 * (i / (data.length - 1 || 1))} />;
 })}
 </svg>
 );
}

// ---- Horizontal mini bar ----
export function MiniBar({ value, max = 100, severity = "info", height = 8 }: { value: number; max?: number; severity?: Severity; height?: number }) {
 return (
 <span className="grc-minibar" style={{ height }}>
 <span className="grc-minibar__fill" style={{ width: `${Math.min(100, (value / max) * 100)}%`, backgroundColor: sevColor(severity) }} />
 </span>
 );
}
