import type { Severity } from "../data/mockData";

export interface DataQualityIssue {
 type: string;
 label: string;
 count: number;
 severity: Severity;
 detail: string;
}

export const DATA_QUALITY_ISSUES: DataQualityIssue[] = [
 { type: "incomplete", label: "Incomplete Data", count: 14, severity: "watch", detail: "Records missing required attribute values." },
 { type: "stale", label: "Stale Assessments", count: 9, severity: "high", detail: "Risk/control assessments past their refresh date." },
 { type: "missing-owner", label: "Missing Owners", count: 6, severity: "watch", detail: "Records with no accountable owner assigned." },
 { type: "missing-evidence", label: "Missing Evidence", count: 11, severity: "high", detail: "Controls/obligations lacking supporting evidence." },
 { type: "unmapped-control", label: "Unmapped Controls", count: 7, severity: "watch", detail: "Controls not linked to any risk or obligation." },
 { type: "unmapped-reg", label: "Unmapped Regulations", count: 4, severity: "info", detail: "Obligations without control mapping." }
];

export const DATA_QUALITY = {
 score: 93,
 previousScore: 91,
 trendPct: 2.2,
 trendDir: "up" as const,
 totalFlags: DATA_QUALITY_ISSUES.reduce((a, i) => a + i.count, 0),
 issues: DATA_QUALITY_ISSUES
};

export function dataQualitySeverity(score: number): Severity {
 if (score >= 95) return "healthy";
 if (score >= 85) return "watch";
 if (score >= 70) return "high";
 return "critical";
}
","import React from "react";
import { Button } from "@servicenow/react-components/Button";
