","// Aggregates all domain KPIs and exposes lookups.
import type { KpiDef } from "../kpiModel";
import { RISK_KPIS } from "./risk";
import { CONTROL_KPIS } from "./controls";
import { REGULATORY_KPIS } from "./regulatory";
import { GOVERNANCE_KPIS } from "./governance";
import { INTERNAL_KPIS } from "./internal";
import { ASSURANCE_KPIS } from "./assurance";
import { REMEDIATION_KPIS } from "./remediation";

export const ALL_KPIS: KpiDef[] = [
 ...RISK_KPIS,
 ...CONTROL_KPIS,
 ...REGULATORY_KPIS,
 ...GOVERNANCE_KPIS,
 ...INTERNAL_KPIS,
 ...ASSURANCE_KPIS,
 ...REMEDIATION_KPIS
];

const KPI_INDEX: Record<string, KpiDef> = ALL_KPIS.reduce((acc, k) => {
 acc[k.id] = k;
 return acc;
}, {} as Record<string, KpiDef>);

export function getKpi(id: string): KpiDef | undefined {
 return KPI_INDEX[id];
}

export function kpisForTab(tab: string): KpiDef[] {
 return ALL_KPIS.filter(k => k.tab === tab);
}

export function kpisForDomain(domain: string): KpiDef[] {
 return ALL_KPIS.filter(k => k.domain === domain);
}

// The 8 headline KPIs shown in the overview strip (stable ids from Prompt 1).
export const STRIP_KPI_IDS = [
 "exposure", "appetite", "ctrl-eff", "ctrl-fail", "reg-comp", "violations", "overdue", "policy"
] as const;

export const STRIP_KPIS: KpiDef[] = STRIP_KPI_IDS
 .map(id => KPI_INDEX[id])
 .filter(Boolean) as KpiDef[];
","// Threshold configuration + status evaluation.
import type { Severity } from "../data/mockData";

export interface ThresholdConfig {
 target: number;
 warning: number;
 critical: number;
 higherIsBetter: boolean;
 label?: string;
}

// Named, configurable threshold presets (as specified by the business).
export const THRESHOLDS: Record<string, ThresholdConfig> = {
 controlEffectiveness: { target: 95, warning: 90, critical: 90, higherIsBetter: true, label: "≥95 target · 90-94 warn · <90 crit" },
 regulatoryCompliance: { target: 97, warning: 92, critical: 92, higherIsBetter: true, label: "≥97 target · 92-96 warn · <92 crit" },
 overdueCriticalActions: { target: 0, warning: 3, critical: 3, higherIsBetter: false, label: "0 target · 1-3 warn · >3 crit" },
 risksOutsideAppetite: { target: 0, warning: 3, critical: 3, higherIsBetter: false, label: "0 target · 1-3 warn · >3 crit" },
 doaCompliance: { target: 98, warning: 95, critical: 95, higherIsBetter: true, label: "≥98 target · 95-97 warn · <95 crit" }
};

// Evaluate a value against a threshold config and return a Severity.
// Risk/count indicators increasing = negative (higherIsBetter=false);
// compliance/effectiveness increasing = positive (higherIsBetter=true).
export function evaluateStatus(
 value: number,
 cfg: { target: number; warning: number; critical: number },
 higherIsBetter: boolean
): Severity {
 const { target, warning, critical } = cfg;
 if (higherIsBetter) {
 if (value >= target) return "healthy";
 if (value >= warning) return "watch";
 if (value >= critical) return "high";
 return "critical";
 }
 if (value <= target) return "healthy";
 if (value <= warning) return "watch";
 if (value <= critical) return "high";
 return "critical";
}

// Convenience: evaluate directly from a KPI-shaped object.
export function evaluateKpiStatus(k: {
 value: number;
 target: number;
 warningThreshold: number;
 criticalThreshold: number;
 higherIsBetter: boolean;
}): Severity {
 return evaluateStatus(
 k.value,
 { target: k.target, warning: k.warningThreshold, critical: k.criticalThreshold },
 k.higherIsBetter
 );
}

export function statusLabel(sev: Severity): string {
 switch (sev) {
 case "healthy": return "On Target";
 case "watch": return "Watch";
 case "high": return "Attention";
 case "critical": return "Action";
 default: return "—";
 }
}
","import React from "react";
import { Card } from "../common/Card";
import { RadialGauge, ProgressRing, Donut, Sparkline, MicroBars } from "../viz/Charts";
import { StatusPill, TrendArrow } from "../viz/Indicators";
import { useApp } from "../../context/AppContext";
import { KPIS, Kpi, Severity } from "../../data/mockData";
import { sevColor } from "../viz/severity";
import { getKpi } from "../../data/kpis";
import { formatKpiValue } from "../../data/kpiModel";
import { evaluateStatus, statusLabel } from "../../logic/thresholds";

function scaleValue(value: string, scale: (n: number) => number, buFocused: boolean): string {
 if (!buFocused) return value;
 const m = value.match(/^(\d+(?:\.\d+)?)(.*)$/);
 if (!m) return value;
 const n = parseFloat(m[1]);
 const scaled = m[1].includes(".") ? (n).toFixed(0) : scale(n);
 return `${scaled}${m[2]}`;
}

function KpiViz({ kpi, scale }: { kpi: Kpi; scale: (n: number) => number }) {
 const sev = kpi.status as Severity;
 const data = kpi.data.map(d => (d <= 5 ? d : scale(d)));
 switch (kpi.viz) {
 case "sparkline":
 return <Sparkline data={data} severity={sev} width={110} height={34} />;
 case "trend":
 return <Sparkline data={data} severity={sev} area={false} width={110} height={34} />;
 case "bars":
 return <MicroBars data={data} severity={sev} width={110} height={34} />;
 case "radial":
 return <RadialGauge value={kpi.data[0]} severity={sev} label={`${kpi.data[0]}%`} size={62} />;
 case "ring":
 return <ProgressRing value={kpi.data[0]} severity={sev} size={56} />;
 case "donut":
 return <Donut size={54} segments={[{ value: kpi.data[0], severity: sev }, { value: 100 - kpi.data[0], severity: "neutral" }]} />;
 case "distribution":
 return (
 <div className="grc-kpi__dist" title="2 Critical, 5 High">
 <span style={{ height: 22, backgroundColor: sevColor("critical") }} />
 <span style={{ height: 34, backgroundColor: sevColor("high") }} />
 </div>
 );
 case "urgency":
 return (
 <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
 <ProgressRing value={78} severity="critical" size={48} text="!" />
 </div>
 );
 default:
 return <Sparkline data={data} severity={sev} width={110} height={34} />;
 }
}

export function KpiStrip({ onOpenKpi }: { onOpenKpi: (kpi: Kpi) => void }) {
 const { scale, buFocused } = useApp();
 return (
 <div className="grc-kpis">
 {KPIS.map(kpi => {
 // Source value / change / status from the surviving KPI model so figures
 // stay consistent and non-round; viz keeps its Prompt-1 shape.
 const m = getKpi(kpi.id);
 const sev = (m
 ? evaluateStatus(m.value, { target: m.target, warning: m.warningThreshold, critical: m.criticalThreshold }, m.higherIsBetter)
 : (kpi.status as Severity)) as Severity;
 const valueText = m ? formatKpiValue(m) : kpi.value;
 const label = m ? statusLabel(sev) : kpi.statusLabel;
 const changeDir = m ? m.trendDir : kpi.changeDir;
 const changeText = m ? `${m.trendPct > 0 ? "+" : ""}${m.trendPct}%` : kpi.change;
 const tip = (m && m.whatItMeans) ? m.whatItMeans : kpi.title;
 return (
 <Card key={kpi.id} className="grc-kpi" accent={sev} onClick={() => onOpenKpi(kpi)}>
 <div className="grc-kpi__top" title={tip}>
 <span className="grc-kpi__title">{kpi.title}</span>
 <StatusPill severity={sev} label={label} size="sm" />
 </div>
 <div className="grc-kpi__value">{scaleValue(valueText, scale, buFocused)}</div>
 {changeText ? (
 <span className="grc-kpi__change">
 {changeDir ? <TrendArrow dir={changeDir} text={changeText} /> : changeText}
 </span>
 ) : null}
 <div className="grc-kpi__viz">
 <KpiViz kpi={kpi} scale={scale} />
 </div>
 {kpi.footnote ? <span className="grc-kpi__foot">{kpi.footnote}</span> : null}
 </Card>
 );
 })}
 </div>
 );
}
","import React from "react";
import { RISK_BUBBLES, RISK_CATEGORY_COLORS, RiskBubble } from "../../data/mockData";
import { appetiteSeverity, sevColor } from "./severity";

const APPETITE_OUTLINE: Record<string, string> = {
 within: "rgb(var(--grc-healthy))",
 approaching: "rgb(var(--grc-watch))",
 above: "rgb(var(--grc-critical))",
 breach: "rgb(var(--grc-critical))"
};

export function RiskHeatmap({ risks = RISK_BUBBLES, onSelect }: { risks?: RiskBubble[]; onSelect?: (r: RiskBubble) => void }) {
 const W = 560;
 const H = 420;
 const pad = 48;
 const plotW = W - pad * 2;
 const plotH = H - pad * 2;
 const x = (likelihood: number) => pad + ((likelihood - 0.5) / 4.5) * plotW;
 const y = (impact: number) => H - pad - ((impact - 0.5) / 4.5) * plotH;

 return (
 <svg className="grc-heatmap" viewBox={`0 0 ${W} ${H}`} width="100%" role="img" aria-label="Enterprise risk heatmap by impact and likelihood">
 {/* risk zones */}
 <defs>
 <linearGradient id="zoneGrad" x1="0" y1="1" x2="1" y2="0">
 <stop offset="0%" stopColor="rgb(var(--grc-healthy))" stopOpacity="0.10" />
 <stop offset="50%" stopColor="rgb(var(--grc-watch))" stopOpacity="0.12" />
 <stop offset="100%" stopColor="rgb(var(--grc-critical))" stopOpacity="0.16" />
 </linearGradient>
 </defs>
 <rect x={pad} y={pad} width={plotW} height={plotH} rx="10" fill="url(#zoneGrad)" stroke="rgba(var(--grc-track),0.9)" />
 {/* gridlines */}
 {[1, 2, 3, 4].map(i => (
 <g key={i} stroke="rgba(var(--grc-track),0.7)" strokeDasharray="3 4">
 <line x1={pad + (i / 5) * plotW} y1={pad} x2={pad + (i / 5) * plotW} y2={H - pad} />
 <line x1={pad} y1={pad + (i / 5) * plotH} x2={W - pad} y2={pad + (i / 5) * plotH} />
 </g>
 ))}
 {/* axis labels */}
 <text x={W / 2} y={H - 12} textAnchor="middle" className="grc-heatmap__axis">Likelihood →</text>
 <text x={16} y={H / 2} textAnchor="middle" className="grc-heatmap__axis" transform={`rotate(-90 16 ${H / 2})`}>Impact →</text>
 {/* bubbles */}
 {risks.map(r => {
 const radius = 12 + (r.exposure / 100) * 26;
 const sev = appetiteSeverity(r.appetite);
 return (
 <g key={r.id} className="grc-heatmap__bubble" onClick={() => onSelect?.(r)} role="button" tabIndex={0}
 aria-label={`${r.name}, ${r.category}, appetite ${r.appetite}`}>
 <circle cx={x(r.likelihood)} cy={y(r.impact)} r={radius}
 fill={RISK_CATEGORY_COLORS[r.category] || "#64748b"} fillOpacity="0.5"
 stroke={APPETITE_OUTLINE[r.appetite]} strokeWidth="2.5" />
 <circle cx={x(r.likelihood)} cy={y(r.impact)} r="3" fill={sevColor(sev)} />
 <text x={x(r.likelihood)} y={y(r.impact) + radius + 12} textAnchor="middle" className="grc-heatmap__label">{r.name}</text>
 </g>
 );
 })}
 </svg>
 );
}

// Compact heatmap tile for domain cards (3x3 grid of cells).
export function MiniHeatmap() {
 const cells = [1, 2, 3, 2, 3, 4, 3, 4, 5];
 const col = (v: number) => (v >= 4 ? "rgb(var(--grc-critical))" : v === 3 ? "rgb(var(--grc-watch))" : "rgb(var(--grc-healthy))");
 return (
 <div className="grc-miniheat" aria-hidden="true">
 {cells.map((v, i) => (
 <span key={i} style={{ backgroundColor: col(v), opacity: 0.35 + v * 0.12 }} />
 ))}
 </div>
 );
}
