","// Executive priority scoring for issues (0-100 weighted model).
import type { Issue } from "../data/content";

export interface PriorityInputs {
 severity: number; // each factor 0-1
 financialExposure: number;
 appetiteBreach: number;
 regulatoryImpact: number;
 controlCriticality: number;
 age: number;
 remediationDelay: number;
 repeatOccurrence: number;
 entitySpread: number;
}

export const PRIORITY_WEIGHTS: Record<keyof PriorityInputs, number> = {
 severity: 20,
 financialExposure: 15,
 appetiteBreach: 15,
 regulatoryImpact: 10,
 controlCriticality: 10,
 age: 10,
 remediationDelay: 10,
 repeatOccurrence: 5,
 entitySpread: 5
};

export type PriorityBand = "Normal" | "Watch" | "High" | "Critical";

export function priorityBand(score: number): { band: PriorityBand; severity: "healthy" | "watch" | "high" | "critical" } {
 if (score >= 80) return { band: "Critical", severity: "critical" };
 if (score >= 60) return { band: "High", severity: "high" };
 if (score >= 40) return { band: "Watch", severity: "watch" };
 return { band: "Normal", severity: "healthy" };
}

export function executivePriorityScore(inputs: Partial<PriorityInputs>): number {
 let score = 0;
 (Object.keys(PRIORITY_WEIGHTS) as (keyof PriorityInputs)[]).forEach(k => {
 const v = Math.max(0, Math.min(1, inputs[k] ?? 0));
 score += v * PRIORITY_WEIGHTS[k];
 });
 return Math.round(score);
}

// Parse "SAR 8.2M" / "High" into a 0-1 exposure factor.
function exposureFactor(exposure: string): number {
 const m = exposure.match(/([\d.]+)/);
 if (m) return Math.min(1, parseFloat(m[1]) / 10); // SAR 10M = max
 if (/high/i.test(exposure)) return 0.7;
 if (/medium/i.test(exposure)) return 0.45;
 return 0.3;
}

function ageFactor(age: string): number {
 const m = age.match(/(\d+)/);
 if (!m) return 0.2;
 return Math.min(1, parseInt(m[1], 10) / 30); // 30 days = max
}

// Derive priority inputs from an Issue, honouring explicit priorityInputs if present.
export function issuePriorityInputs(issue: Issue): PriorityInputs {
 if (issue.priorityInputs) return issue.priorityInputs;
 const crit = issue.priority === "CRITICAL";
 return {
 severity: crit ? 1 : 0.65,
 financialExposure: exposureFactor(issue.exposure),
 appetiteBreach: /appetite|above|breach/i.test(issue.affectedRisk) ? (crit ? 0.9 : 0.7) : 0.3,
 regulatoryImpact: /direct|sox|mandatory|regulatory/i.test(issue.regulatoryImpact) ? 0.8 : 0.4,
 controlCriticality: /CTRL/.test(issue.affectedControls) ? (crit ? 0.9 : 0.6) : 0.3,
 age: ageFactor(issue.age),
 remediationDelay: issue.status === "Overdue" ? 1 : issue.status === "Escalating" ? 0.6 : 0.3,
 repeatOccurrence: /repeat|recurring|third|consecutive/i.test(issue.summary) ? 0.9 : 0.2,
 entitySpread: /across|multiple|and procurement|finance and/i.test(issue.businessImpact) ? 0.6 : 0.3
 };
}

export function scoreIssue(issue: Issue): number {
 return executivePriorityScore(issuePriorityInputs(issue));
}

// Issues ranked by executive priority (desc).
export function rankIssues(issues: Issue[]): { issue: Issue; score: number; band: PriorityBand }[] {
 return issues
 .map(issue => {
 const score = scoreIssue(issue);
 return { issue, score, band: priorityBand(score).band };
 })
 .sort((a, b) => b.score - a.score);
}
