","// Cross-domain relationship graph for the GRC chain + lateral links.
// Chain: Regulation→Requirement→Policy→Control→Risk→Issue→Remediation→Assurance.
// Lateral: Risk↔Control, Policy↔Regulation, Policy↔Process, Control↔Test,
// Test↔Exception, Exception↔Issue, Issue↔Action, Risk↔KRI, Risk↔BU,
// Risk↔Entity, Control↔BU, DoAException↔Policy, DoAException↔Transaction.
import { RISK_BUBBLES } from "./mockData";
import { ISSUES } from "./content";
import { getKpi } from "./kpis";
import { RISK_ATTRIBUTES } from "./models/risk";
import { CONTROL_ATTRIBUTES } from "./models/controls";
import { GOVERNANCE_ATTRIBUTES, DOA_TRANSACTIONS } from "./models/governance";
import { REGULATORY_ATTRIBUTES } from "./models/regulatory";
import { ASSURANCE_ATTRIBUTES } from "./models/assurance";
import { REMEDIATIONS } from "./kpis/remediation";

export type EntityType =
 | "regulation" | "requirement" | "policy" | "control" | "risk" | "issue"
 | "remediation" | "action" | "assurance" | "process" | "test" | "exception"
 | "kri" | "bu" | "entity" | "transaction" | "doaException" | "kpi";

export interface RelatedRef { type: EntityType; id: string; label: string; }

type Edge = [EntityType, string, EntityType, string];
const E: Edge[] = [];
const link = (ta: EntityType, ia: string, tb: EntityType, ib: string) => E.push([ta, ia, tb, ib]);

REGULATORY_ATTRIBUTES.forEach(r => {
 const req = `req-${r.id}`;
 link("regulation", r.id, "requirement", req);
 r.affectedPolicies.forEach(p => link("requirement", req, "policy", p));
 r.affectedControls.forEach(c => link("regulation", r.id, "control", c));
 r.affectedRisks.forEach(rk => link("regulation", r.id, "risk", rk));
});
GOVERNANCE_ATTRIBUTES.forEach(p => {
 link("policy", p.policyId, "process", `proc-${p.bu.toLowerCase()}`);
 p.linkedControls.forEach(c => link("policy", p.policyId, "control", c));
 p.linkedRegulations.forEach(rg => link("policy", p.policyId, "regulation", rg));
});
CONTROL_ATTRIBUTES.forEach(c => {
 link("control", c.id, "risk", c.relatedRisk);
 link("control", c.id, "test", `test-${c.id}`);
 link("control", c.id, "bu", c.bu);
 if (c.openExceptions > 0) link("test", `test-${c.id}`, "exception", `exc-${c.id}`);
});
RISK_ATTRIBUTES.forEach(r => {
 link("risk", r.id, "kri", `kri-${r.id}`);
 link("risk", r.id, "bu", r.bu);
 link("risk", r.id, "entity", r.entity);
});
ISSUES.forEach(it => {
 (it.relatedRiskIds || []).forEach(r => link("risk", r, "issue", it.id));
 (it.relatedControlIds || []).forEach(c => { link("control", c, "issue", it.id); link("exception", `exc-${c}`, "issue", it.id); });
 (it.relatedRemediationIds || []).forEach(a => link("issue", it.id, "remediation", a));
});
REMEDIATIONS.forEach(a => {
 if (a.issue) link("issue", a.issue, "remediation", a.actionId);
 if (a.relatedControl) link("control", a.relatedControl, "remediation", a.actionId);
 if (a.relatedRisk) link("risk", a.relatedRisk, "remediation", a.actionId);
 if (a.relatedPolicy) link("policy", a.relatedPolicy, "remediation", a.actionId);
});
ASSURANCE_ATTRIBUTES.forEach(as => {
 if (as.risk) link("risk", as.risk, "assurance", as.id);
 if (as.control) link("control", as.control, "assurance", as.id);
 REMEDIATIONS.filter(a => a.relatedRisk === as.risk).forEach(a => link("remediation", a.actionId, "assurance", as.id));
});
DOA_TRANSACTIONS.forEach(t => {
 if (t.status === "within-limit") return;
 const ex = `doae-${t.transaction}`;
 link("doaException", ex, "transaction", t.transaction);
 link("doaException", ex, "policy", t.policy);
});

export function labelFor(type: EntityType, id: string): string {
 switch (type) {
 case "regulation": { const r = REGULATORY_ATTRIBUTES.find(x => x.id === id); return r ? `${r.regulator} — ${r.regulation}` : id; }
 case "requirement": { const r = REGULATORY_ATTRIBUTES.find(x => `req-${x.id}` === id); return r ? r.requirement : id; }
 case "policy": { const p = GOVERNANCE_ATTRIBUTES.find(x => x.policyId === id); return p ? `${p.name} ${p.version}` : id; }
 case "control": { const c = CONTROL_ATTRIBUTES.find(x => x.id === id); return c ? `${c.id} ${c.name}` : id; }
 case "risk": { const r = RISK_BUBBLES.find(x => x.id === id) || RISK_ATTRIBUTES.find(x => x.id === id); return r ? r.name : id; }
 case "issue": { const it = ISSUES.find(x => x.id === id); return it ? it.issue : id; }
 case "remediation": case "action": { const a = REMEDIATIONS.find(x => x.actionId === id); return a ? `${a.actionId.toUpperCase()} · ${a.domain}` : id; }
 case "assurance": { const a = ASSURANCE_ATTRIBUTES.find(x => x.id === id); return a ? a.assuranceActivity : id; }
 case "kri": { const r = RISK_ATTRIBUTES.find(x => `kri-${x.id}` === id); return r ? `KRI — ${r.name}` : id; }
 case "test": { const c = CONTROL_ATTRIBUTES.find(x => `test-${x.id}` === id); return c ? `Test — ${c.name}` : id; }
 case "exception": { const c = CONTROL_ATTRIBUTES.find(x => `exc-${x.id}` === id); return c ? `Exception — ${c.id}` : id; }
 case "process": return id.replace("proc-", "").replace(/^\w/, m => m.toUpperCase()) + " Process";
 case "transaction": { const t = DOA_TRANSACTIONS.find(x => x.transaction === id); return t ? `${t.transaction} (${t.bu})` : id; }
 case "doaException": { const t = DOA_TRANSACTIONS.find(x => `doae-${x.transaction}` === id); return t ? `DoA Exception — ${t.transaction}` : id; }
 case "kpi": { const k = getKpi(id); return k ? k.name : id; }
 default: return id;
 }
}

function kpiRelated(kpiId: string): RelatedRef[] {
 const k = getKpi(kpiId);
 if (!k) return [];
 const refs: RelatedRef[] = [];
 const push = (t: EntityType, ids: string[]) => ids.forEach(i => refs.push({ type: t, id: i, label: labelFor(t, i) }));
 push("risk", k.relatedRisks); push("control", k.relatedControls); push("policy", k.relatedPolicies);
 push("regulation", k.relatedRegulations); push("issue", k.relatedIssues);
 push("remediation", k.relatedRemediations); push("assurance", k.relatedAssurance);
 return refs;
}

export function getRelated(type: EntityType, id: string): RelatedRef[] {
 if (type === "kpi") return kpiRelated(id);
 const out: RelatedRef[] = [];
 const seen = new Set<string>();
 const add = (t: EntityType, i: string) => {
 const key = `${t}:${i}`;
 if (seen.has(key)) return;
 seen.add(key);
 out.push({ type: t, id: i, label: labelFor(t, i) });
 };
 E.forEach(([ta, ia, tb, ib]) => {
 if (ta === type && ia === id) add(tb, ib);
 else if (tb === type && ib === id) add(ta, ia);
 });
 return out;
}
","// Executive Insight model — strict 6-part structure keyed by KPI id.
import { getKpi } from "./kpis";
import { formatKpiValue } from "./kpiModel";

export interface ExecutiveInsight {
 signal: string;
 impact: string;
 cause: string;
 prediction: string;
 recommendation: string;
 action: string;
 // Optional, non-breaking extras consumed by the KPI drawer.
