import { Header } from "./components/layout/Header";
import { TabNav, Breadcrumbs } from "./components/layout/TabNav";
import { ExecutiveOverview } from "./components/overview/ExecutiveOverview";
import { TabView } from "./components/tabs/TabView";
import { IssueDrawer } from "./components/drawer/IssueDrawer";
import { KpiDrawer } from "./components/drawer/KpiDrawer";
import { AiPanel } from "./components/ai/AiPanel";
import { FloatingAi } from "./components/ai/FloatingAi";
import { useRouter } from "./router/useRouter";
import { useApp } from "./context/AppContext";
import { TABS, Kpi, RiskBubble } from "./data/mockData";
import { ISSUES } from "./data/content";
import { getKpi } from "./data/kpis";

function titleFor(tab: string) {
 const meta = TABS.find(t => t.id === tab);
 return `GRC VP Command Center — ${meta?.label || "Overview"}`;
}

function mapRiskToIssue(r: RiskBubble): string {
 const byBu = ISSUES.find(i => i.bu === r.bu);
 return byBu ? byBu.id : ISSUES[0].id;
}

export default function App() {
 const { route, navigate, goTab } = useRouter();
 const { aiPanelOpen, setAiPanelOpen } = useApp();

 const openIssue = useCallback((id: string) => {
 const issue = ISSUES.find(i => i.id === id);
 navigate({ view: "detail", id }, `GRC — ${issue?.issue || "Issue"}`);
 }, [navigate]);

 const closeDrawer = useCallback(() => {
 navigate({ view: null, id: null }, titleFor(route.tab));
 }, [navigate, route.tab]);

 const onOpenTab = useCallback((tab: string) => goTab(tab, titleFor(tab)), [goTab]);
 const onSelectRisk = useCallback((r: RiskBubble) => openIssue(mapRiskToIssue(r)), [openIssue]);

 const onOpenKpi = useCallback((k: Kpi | string) => {
 const id = typeof k === "string" ? k : k.id;
 const name = getKpi(id)?.name || (typeof k === "string" ? id : k.title);
 navigate({ view: "kpi", id }, `GRC — ${name}`);
 }, [navigate]);

 const activeTab = TABS.find(t => t.id === route.tab);
 const drawerIssueId = route.view === "detail" ? route.id : null;
 const drawerKpiId = route.view === "kpi" ? route.id : null;
 const showAiPanel = route.tab !== "ai";

 const crumbs: { label: string; onClick?: () => void }[] = [
 { label: "Executive Overview", onClick: () => onOpenTab("overview") }
 ];
 if (route.tab !== "overview") crumbs.push({ label: activeTab?.label || route.tab, onClick: () => onOpenTab(route.tab) });
 if (drawerIssueId) crumbs.push({ label: ISSUES.find(i => i.id === drawerIssueId)?.issue || "Issue" });
 if (drawerKpiId) crumbs.push({ label: getKpi(drawerKpiId)?.name || "KPI" });

 return (
 <div className="grc-app">
 <div className="grc-shell">
 <Header onToggleAi={() => setAiPanelOpen(!aiPanelOpen)} />
 <div className="grc-body">
 <TabNav active={route.tab} onSelect={onOpenTab} />
 <main className="grc-main">
 {(route.tab !== "overview" || drawerIssueId || drawerKpiId) ? <Breadcrumbs items={crumbs} /> : null}
 {route.tab === "overview"
 ? <ExecutiveOverview onOpenTab={onOpenTab} onOpenIssue={openIssue} onSelectRisk={onSelectRisk} onOpenKpi={onOpenKpi} />
 : <TabView tab={route.tab} onOpenIssue={openIssue} onSelectRisk={onSelectRisk} />}
 </main>
 {showAiPanel ? <AiPanel open={aiPanelOpen} onToggle={() => setAiPanelOpen(!aiPanelOpen)} /> : null}
 </div>
 </div>

 {drawerIssueId ? <IssueDrawer issueId={drawerIssueId} onClose={closeDrawer} /> : null}
 {drawerKpiId ? <KpiDrawer kpiId={drawerKpiId} onClose={closeDrawer} onOpenIssue={openIssue} onOpenTab={onOpenTab} /> : null}
 <FloatingAi panelOpen={showAiPanel && aiPanelOpen} />
 </div>
 );
}
","import React from "react";
import ReactDOM from "react-dom/client";
import App from "./app";
import { ThemeProvider } from "./context/ThemeContext";
import { AppProvider } from "./context/AppContext";
import { ActionsProvider } from "./components/common/Actions";

const container = document.getElementById("root");
if (container) {
 ReactDOM.createRoot(container).render(
 <ThemeProvider>
 <AppProvider>
 <ActionsProvider>
 <App />
 </ActionsProvider>
 </AppProvider>
 </ThemeProvider>
 );
}
